// Inputs: date (YYYY-MM-DD), team_member_id (uuid|null), service_id, duration_minutes.
// Replace the empty bookings/businessHours/techAvail arrays below with real
// Supabase nodes wired into this Code node.
const { date, team_member_id, duration_minutes } = $json;

const businessHours = []; // ← read business_hours where day_of_week = JS getDay(date)
const row = businessHours[0];
const isOpen = Boolean(row && row.is_open);
if (!isOpen) {
  return [{ json: { is_open: false, open_time: null, close_time: null, tech_works_today: false, available_slots: [] } }];
}

const openTime = row.open_time;
const closeTime = row.close_time;

// All techs working that day
const techAvail = [];   // ← read tech_availability where day_of_week = JS getDay(date)
const techsToday = techAvail.map(t => t.team_member_id);
const techWorksToday = team_member_id
  ? techsToday.includes(team_member_id)
  : techsToday.length > 0;

if (!techWorksToday) {
  return [{ json: { is_open: true, open_time: openTime, close_time: closeTime, tech_works_today: false, available_slots: [] } }];
}

// Existing segments on that date for the relevant techs (NOT cancelled)
const segments = []; // ← join appointment_segments + bookings where date matches and status != 'CANCELLED'

function toMin(hhmm) { return parseInt(hhmm.slice(0,2),10)*60 + parseInt(hhmm.slice(3,5),10); }
function toHHMM(m) {
  const h = String(Math.floor(m/60)).padStart(2,'0');
  const mm = String(m%60).padStart(2,'0');
  return `${h}:${mm}`;
}

const openMin = toMin(openTime);
const closeMin = toMin(closeTime);
const dur = Number(duration_minutes);

const conflictsByTech = new Map();
for (const s of segments) {
  const startMin = toMin(s.start_at.slice(11,16));
  const endMin = startMin + Number(s.duration_minutes);
  if (!conflictsByTech.has(s.team_member_id)) conflictsByTech.set(s.team_member_id, []);
  conflictsByTech.get(s.team_member_id).push([startMin, endMin]);
}

function techFree(tid, startMin, endMin) {
  const list = conflictsByTech.get(tid) || [];
  return list.every(([a, b]) => endMin <= a || startMin >= b);
}

const slots = [];
for (let m = openMin; m + dur <= closeMin; m += 30) {
  const candidates = team_member_id ? [team_member_id] : techsToday;
  if (candidates.some(tid => techFree(tid, m, m + dur))) {
    slots.push(toHHMM(m));
  }
}

return [{ json: { is_open: true, open_time: openTime, close_time: closeTime, tech_works_today: true, available_slots: slots } }];
